SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
IF EXISTS(SELECT 1 FROM dbo.SchemaMigration WHERE Version='008') BEGIN PRINT '008 already applied'; RETURN; END;
BEGIN TRY BEGIN TRANSACTION;
CREATE TABLE cfg.LanguagePresentation(LanguageId bigint PRIMARY KEY REFERENCES cfg.Language(Id),NativeName nvarchar(100) NOT NULL,Direction varchar(3) NOT NULL CHECK(Direction IN ('ltr','rtl')),IsInterfaceEnabled bit NOT NULL DEFAULT 0,FallbackLanguageId bigint NULL REFERENCES cfg.Language(Id),CHECK(FallbackLanguageId IS NULL OR FallbackLanguageId<>LanguageId));
CREATE TABLE cfg.TextResource(ResourceKey varchar(180) PRIMARY KEY,SourceText nvarchar(2000) NOT NULL,ContextLabel nvarchar(200) NULL);
CREATE TABLE cfg.RouteAlias(LegacyRoute nvarchar(200) PRIMARY KEY,TargetRoute nvarchar(200) NOT NULL,CHECK(LegacyRoute<>TargetRoute));
CREATE TABLE food.IngredientPresentation(IngredientId bigint PRIMARY KEY REFERENCES food.Ingredient(Id),CategoryCode varchar(30) NOT NULL CHECK(CategoryCode IN ('GrainsPulses','Vegetables','Dairy','Other')),AccentColor char(7) NOT NULL CHECK(AccentColor LIKE '#[0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f]'),SortOrder int NOT NULL DEFAULT 0,ImageState varchar(20) NOT NULL DEFAULT 'Pending' CHECK(ImageState IN ('Pending','Ready')),Version rowversion NOT NULL);
CREATE TABLE commerce.DemoProduct(Id bigint IDENTITY PRIMARY KEY,Code varchar(60) UNIQUE NOT NULL,Name nvarchar(150) NOT NULL,PackDescription nvarchar(100) NOT NULL,Category nvarchar(80) NOT NULL,IsIllustrative bit NOT NULL DEFAULT 1 CHECK(IsIllustrative=1));
CREATE TABLE commerce.DemoOffer(ProductId bigint NOT NULL REFERENCES commerce.DemoProduct(Id),ProviderId bigint NOT NULL REFERENCES commerce.Provider(Id),CurrencyCode char(3) NOT NULL DEFAULT 'INR',PackPrice decimal(18,2) NULL CHECK(PackPrice>=0),PRIMARY KEY(ProductId,ProviderId));
CREATE TABLE family.InterfacePreference(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,UserId bigint NOT NULL,LanguageId bigint NOT NULL REFERENCES cfg.Language(Id),ThemeId bigint NULL REFERENCES cfg.Theme(Id),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,UserId) REFERENCES family.Membership(HouseholdId,UserId),UNIQUE(HouseholdId,UserId));
CREATE TABLE finance.PlanScenario(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,Name nvarchar(150) NOT NULL,CurrencyCode char(3) NOT NULL DEFAULT 'INR',AsOfDate date NOT NULL,CalculationVersion varchar(40) NOT NULL DEFAULT 'aarohi-plan-v1',InflationPercent decimal(7,3) NOT NULL DEFAULT 6 CHECK(InflationPercent>-100 AND InflationPercent<=100),BeforeReturnPercent decimal(7,3) NOT NULL DEFAULT 8 CHECK(BeforeReturnPercent>-100 AND BeforeReturnPercent<=100),AfterReturnPercent decimal(7,3) NOT NULL DEFAULT 6 CHECK(AfterReturnPercent>-100 AND AfterReturnPercent<=100),EndAge smallint NOT NULL DEFAULT 85 CHECK(EndAge BETWEEN 1 AND 120),RetireSpendPercent decimal(7,2) NOT NULL DEFAULT 100 CHECK(RetireSpendPercent BETWEEN 0 AND 300),RetireSaved decimal(18,2) NOT NULL DEFAULT 0 CHECK(RetireSaved>=0),RetireContribution decimal(18,2) NOT NULL DEFAULT 0 CHECK(RetireContribution>=0),MonthlyPension decimal(18,2) NOT NULL DEFAULT 0 CHECK(MonthlyPension>=0),EmergencyMonths smallint NOT NULL DEFAULT 6 CHECK(EmergencyMonths BETWEEN 1 AND 60),EmergencySaved decimal(18,2) NOT NULL DEFAULT 0 CHECK(EmergencySaved>=0),EmergencyContribution decimal(18,2) NOT NULL DEFAULT 0 CHECK(EmergencyContribution>=0),SupportYears smallint NOT NULL DEFAULT 15 CHECK(SupportYears BETWEEN 1 AND 100),SupportDiscountPercent decimal(7,3) NOT NULL DEFAULT 4 CHECK(SupportDiscountPercent>-100 AND SupportDiscountPercent<=100),SupportAssets decimal(18,2) NOT NULL DEFAULT 0 CHECK(SupportAssets>=0),HealthCoverTarget decimal(18,2) NOT NULL DEFAULT 0 CHECK(HealthCoverTarget>=0),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id));
CREATE TABLE finance.PlanPerson(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,ScenarioId bigint NOT NULL,MemberId bigint NULL,Name nvarchar(150) NOT NULL,DateOfBirth date NOT NULL,RetirementAge smallint NOT NULL DEFAULT 60 CHECK(RetirementAge BETWEEN 1 AND 119),IsRetirementPerson bit NOT NULL DEFAULT 0,CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId) REFERENCES finance.PlanScenario(HouseholdId,Id),FOREIGN KEY(HouseholdId,MemberId) REFERENCES family.Member(HouseholdId,Id),UNIQUE(HouseholdId,ScenarioId,Id));
CREATE UNIQUE INDEX UX_Plan_RetirementPerson ON finance.PlanPerson(HouseholdId,ScenarioId) WHERE IsRetirementPerson=1;
CREATE TABLE finance.PlanAsset(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,ScenarioId bigint NOT NULL,Name nvarchar(150) NOT NULL,AssetType nvarchar(80) NOT NULL,CurrentValue decimal(18,2) NOT NULL DEFAULT 0 CHECK(CurrentValue>=0),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId) REFERENCES finance.PlanScenario(HouseholdId,Id));
CREATE TABLE finance.PlanDebt(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,ScenarioId bigint NOT NULL,Name nvarchar(150) NOT NULL,OutstandingBalance decimal(18,2) NOT NULL DEFAULT 0 CHECK(OutstandingBalance>=0),MonthlyEmi decimal(18,2) NOT NULL DEFAULT 0 CHECK(MonthlyEmi>=0),InterestPercent decimal(7,3) NOT NULL DEFAULT 0 CHECK(InterestPercent BETWEEN 0 AND 100),RemainingMonths int NOT NULL DEFAULT 0 CHECK(RemainingMonths BETWEEN 0 AND 1200),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId) REFERENCES finance.PlanScenario(HouseholdId,Id));
CREATE TABLE finance.PlanFlow(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,ScenarioId bigint NOT NULL,Name nvarchar(150) NOT NULL,Kind varchar(25) NOT NULL CHECK(Kind IN ('Income','Essential','Lifestyle','Investment','AnnualReserve')),Amount decimal(18,2) NOT NULL DEFAULT 0 CHECK(Amount>=0),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId) REFERENCES finance.PlanScenario(HouseholdId,Id));
CREATE TABLE finance.PlanPolicy(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,ScenarioId bigint NOT NULL,Name nvarchar(150) NOT NULL,Kind varchar(10) NOT NULL CHECK(Kind IN ('Life','Health')),CoverAmount decimal(18,2) NOT NULL DEFAULT 0 CHECK(CoverAmount>=0),AnnualPremium decimal(18,2) NOT NULL DEFAULT 0 CHECK(AnnualPremium>=0),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId) REFERENCES finance.PlanScenario(HouseholdId,Id));
CREATE TABLE finance.PlanGoal(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,ScenarioId bigint NOT NULL,PersonId bigint NULL,Name nvarchar(150) NOT NULL,CurrentCost decimal(18,2) NOT NULL DEFAULT 0 CHECK(CurrentCost>=0),EarmarkedSavings decimal(18,2) NOT NULL DEFAULT 0 CHECK(EarmarkedSavings>=0),TargetBasis varchar(4) NOT NULL CHECK(TargetBasis IN ('Date','Age')),TargetDate date NULL,TargetAge smallint NULL CHECK(TargetAge BETWEEN 1 AND 120),InflationPercent decimal(7,3) NOT NULL DEFAULT 6 CHECK(InflationPercent>-100 AND InflationPercent<=100),ReturnPercent decimal(7,3) NOT NULL DEFAULT 8 CHECK(ReturnPercent>-100 AND ReturnPercent<=100),CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId) REFERENCES finance.PlanScenario(HouseholdId,Id),FOREIGN KEY(HouseholdId,ScenarioId,PersonId) REFERENCES finance.PlanPerson(HouseholdId,ScenarioId,Id),CHECK((TargetBasis='Date' AND TargetDate IS NOT NULL AND TargetAge IS NULL) OR (TargetBasis='Age' AND PersonId IS NOT NULL AND TargetAge IS NOT NULL AND TargetDate IS NULL)));
CREATE TABLE commerce.QuoteVerification(HouseholdId bigint NOT NULL REFERENCES family.Household(Id),Id bigint IDENTITY NOT NULL,QuoteId bigint NOT NULL,FeesKnown bit NOT NULL DEFAULT 0,ExactBasketMatchVerified bit NOT NULL DEFAULT 0,CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),Version rowversion NOT NULL,PRIMARY KEY(HouseholdId,Id),FOREIGN KEY(HouseholdId,QuoteId) REFERENCES commerce.Quote(HouseholdId,Id),UNIQUE(HouseholdId,QuoteId));
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON family.InterfacePreference, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON family.InterfacePreference AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON family.InterfacePreference AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON family.InterfacePreference TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanScenario, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanScenario AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanScenario AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanScenario TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanPerson, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanPerson AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanPerson AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanPerson TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanAsset, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanAsset AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanAsset AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanAsset TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanDebt, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanDebt AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanDebt AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanDebt TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanFlow, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanFlow AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanFlow AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanFlow TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanPolicy, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanPolicy AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanPolicy AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanPolicy TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanGoal, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanGoal AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON finance.PlanGoal AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON finance.PlanGoal TO aarohi_app;
EXEC(N'ALTER SECURITY POLICY auth.HouseholdIsolation ADD FILTER PREDICATE auth.fnHouseholdAccess(HouseholdId) ON commerce.QuoteVerification, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON commerce.QuoteVerification AFTER INSERT, ADD BLOCK PREDICATE auth.fnHouseholdAccess(HouseholdId) ON commerce.QuoteVerification AFTER UPDATE;');
GRANT SELECT,INSERT,UPDATE,DELETE ON commerce.QuoteVerification TO aarohi_app;
GRANT SELECT ON commerce.DemoProduct TO aarohi_app; GRANT SELECT ON commerce.DemoOffer TO aarohi_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON food.IngredientPresentation TO aarohi_config_admin;
GRANT SELECT,INSERT,UPDATE,DELETE ON commerce.DemoProduct TO aarohi_config_admin;
GRANT SELECT,INSERT,UPDATE,DELETE ON commerce.DemoOffer TO aarohi_config_admin;
INSERT dbo.SchemaMigration(Version) VALUES('008'); COMMIT; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH;
